export async function checkRateLimit(
  userId: string,
  limit = 100,
  windowMs = 60000
): Promise<boolean> {
  const key = `ratelimit:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  // Pipeline multi-step operations to reduce RTT
  const pipeline = redis.pipeline();
  pipeline.zremrangebyscore(key, 0, windowStart); // Drop expired timestamps
  pipeline.zadd(key, now, `${now}-${Math.random()}`); // Add current timestamp
  pipeline.zcard(key); // Count requests in active window
  pipeline.pexpire(key, windowMs); // Reset TTL

  const results = await pipeline.exec();
  const requestCount = results![2][1] as number;
  return requestCount <= limit;
}
